// Every shape that crosses HTTP between the SPA and the API.
// Database row types are generated by Supabase and stay inside apps/api.

import type {
  CatalogUnit,
  Currency,
  DiscountType,
  ErrorCode,
  InviteStatus,
  QuoteEventType,
  QuoteSort,
  QuoteStatus,
  WorkspaceRole,
} from './enums';
import type { QuoteTotals } from './money';

/* ---------- Envelope ---------- */

export interface PageMeta {
  page: number;
  pageSize: number;
  total: number;
}

export interface ApiSuccess<T> {
  data: T;
  meta?: PageMeta;
}

export interface ApiError {
  error: { code: ErrorCode; message: string; details?: unknown; requestId: string };
}

export interface PageQuery {
  page?: number;
  pageSize?: number;
  search?: string;
}

/* ---------- Session & workspace ---------- */

export interface WorkspaceSummary {
  id: string;
  name: string;
  role: WorkspaceRole;
}

export interface Me {
  id: string;
  email: string;
  fullName: string;
  workspaces: WorkspaceSummary[];
}

export interface Workspace {
  id: string;
  name: string;
  currency: Currency;
  taxPercent: number;
  brandAccent: string | null;
  logoUrl: string | null;
}

export interface CreateWorkspaceInput {
  name: string;
  currency: Currency;
  taxPercent: number;
}

export type UpdateWorkspaceInput = Partial<CreateWorkspaceInput> & { brandAccent?: string | null };

/* ---------- Team ---------- */

export interface Member {
  userId: string;
  email: string;
  fullName: string;
  role: WorkspaceRole;
  joinedAt: string;
}

export interface Invite {
  id: string;
  email: string;
  role: WorkspaceRole;
  status: InviteStatus;
  expiresAt: string;
}

export interface CreateInviteInput {
  email: string;
  role: WorkspaceRole;
}

/** Returned once, when the invite is created. The token is never stored in clear. */
export interface CreatedInvite extends Invite {
  inviteUrl: string;
}

export interface UpdateMemberInput {
  role: WorkspaceRole;
}

/* ---------- Customers ---------- */

export interface CustomerInput {
  companyName: string;
  contactName?: string;
  email?: string;
  phone?: string;
  address?: string;
}

export interface Customer extends Required<CustomerInput> {
  id: string;
  archived: boolean;
  createdAt: string;
}

export interface CustomerDetail extends Customer {
  quotes: QuoteListItem[];
}

/* ---------- Catalog ---------- */

export interface CatalogItemInput {
  name: string;
  description?: string;
  unit: CatalogUnit;
  unitPriceMinor: number;
  active?: boolean;
}

export interface CatalogItem extends Required<CatalogItemInput> {
  id: string;
}

/* ---------- Quotes ---------- */

export interface QuoteItemInput {
  catalogItemId?: string | null;
  name: string;
  unit: CatalogUnit;
  quantity: number;
  unitPriceMinor: number;
}

export interface QuoteItem extends QuoteItemInput {
  id: string;
  position: number;
  lineTotalMinor: number;
}

export interface SaveQuoteInput {
  customerId: string;
  title: string;
  validUntil: string;
  items: QuoteItemInput[];
  discountType: DiscountType;
  discountValue: number;
  taxPercent: number;
  notes?: string;
}

export interface QuoteQuery extends PageQuery {
  status?: QuoteStatus;
  customerId?: string;
  sort?: QuoteSort;
}

export interface QuoteListItem extends QuoteTotals {
  id: string;
  number: string;
  title: string;
  status: QuoteStatus;
  currency: Currency;
  customerId: string;
  customerName: string;
  validUntil: string;
  createdAt: string;
}

export interface Quote extends QuoteListItem {
  discountType: DiscountType;
  discountValue: number;
  taxPercent: number;
  notes: string;
  items: QuoteItem[];
  sentAt: string | null;
  viewedAt: string | null;
  respondedAt: string | null;
  clientName: string | null;
  declineReason: string | null;
}

export interface SentQuote {
  quote: Quote;
  /** Shown once. Sending again creates a new link and the old one stops working. */
  shareUrl: string;
}

export interface QuoteEvent {
  id: string;
  type: QuoteEventType;
  actorName: string | null;
  createdAt: string;
}

/* ---------- Public quote (client, no account) ---------- */

export interface PublicQuote extends QuoteTotals {
  number: string;
  title: string;
  status: QuoteStatus;
  currency: Currency;
  validUntil: string;
  sentAt: string;
  notes: string;
  discountType: DiscountType;
  discountValue: number;
  taxPercent: number;
  items: Pick<QuoteItem, 'name' | 'unit' | 'quantity' | 'unitPriceMinor' | 'lineTotalMinor'>[];
  seller: { name: string; logoUrl: string | null; brandAccent: string | null };
  customer: { companyName: string; contactName: string };
  clientName: string | null;
  respondedAt: string | null;
}

export interface RespondQuoteInput {
  accept: boolean;
  clientName: string;
  declineReason?: string;
}

/* ---------- Dashboard ---------- */

export interface ActivityItem {
  quoteId: string;
  quoteNumber: string;
  type: QuoteEventType;
  actorName: string | null;
  createdAt: string;
}

export interface DashboardSummary {
  currency: Currency;
  openValueMinor: number;
  openCount: number;
  wonValueMinor: number;
  winRatePercent: number | null;
  expiringSoon: QuoteListItem[];
  recentActivity: ActivityItem[];
}
